/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useCallback,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  interpolate,
  OffthreadVideo,
  Sequence,
  type SequenceControls,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

const { fontFamily: SANS } = loadInter("normal", {
  weights: ["500", "600", "700"],
  subsets: ["latin"],
});

export interface HeroLaunchProps {
  /** Reveal caption under the cards. */
  heading?: string;
  /**
   * Left card media. An image URL, a video URL (`.mp4`/`.webm`/`.mov` → plays
   * via <OffthreadVideo>), or a CSS `linear-gradient(...)`. The video editor
   * swaps this for the viewer's own image/clip.
   */
  image1?: string;
  /** Right card media (same rules as `image1`). */
  image2?: string;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  /** Defaults to `"dark"` — the scene is a cinematic stage, lit for dark. */
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
}

const PERSP = 1000;
// Pure rotateY about each card's INNER edge — no rotateX, so the inner edges
// stay vertical and the centre gap is a clean, even channel top-to-bottom.
const TILT = 17;
const GAP = 92;
/** Stand-in for missing media — the page lifted a shade, not a fixed grey. */
const placeholder = (t: KitTheme) =>
  `linear-gradient(135deg,${mixOklch(t.background, t.card, 0.55)},${mixOklch(
    t.background,
    t.card,
    0.2,
  )})`;

const isVideo = (src: string) => /\.(mp4|webm|mov|m4v)(\?|$)/i.test(src);
const isGradient = (src: string) => src.startsWith("linear-gradient");

// easeOutQuint — quick to move, silky to settle, lands exactly on target with
// no asymptotic "stuck" tail (the thing overdamped springs get wrong).
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
// Gravity-ish accelerate for the drop-off.
const FALL = Easing.bezier(0.5, 0, 0.9, 0.4);

/**
 * A root-relative asset ("/showcase-assets/..") is served at the origin root by
 * Next in the Player, but Remotion Studio and a render serve `public/` through
 * `staticFile()` alone — so rewrite local paths everywhere but the Player, and pass
 * http(s)/data/blob URLs straight through.
 */
function resolveSrc(src: string): string {
  const isLocal = src.startsWith("/") && !src.startsWith("//");
  if (!isLocal || getRemotionEnvironment().isPlayer) return src;
  // A value that already came out of staticFile() carries the static base
  // (`/static-<hash>/…`); running it through again would prefix it twice.
  const base = staticFile("_").slice(0, -2);
  if (base && src.startsWith(`${base}/`)) return src;
  try {
    return staticFile(src.replace(/^\/+/, ""));
  } catch {
    return src;
  }
}

/**
 * Image that holds the server render until it has actually *loaded*, then
 * releases. Remotion's <Img> is avoided on purpose: it awaits `img.decode()`,
 * which the headless compositor rejects for some progressive JPEGs and hangs the
 * export. A plain <img> paints fine — we wait for `onload` ourselves and clear
 * on error too, so a bad source degrades gracefully. In the Player this is an
 * ordinary, instantly-shown image.
 */
function HeroImage({ src, style }: { src: string; style: CSSProperties }) {
  const [handle] = useState(() => delayRender(`hero image: ${src}`));
  const release = useCallback(() => continueRender(handle), [handle]);
  return (
    // biome-ignore lint/performance/noImgElement: Remotion frame, not a Next route.
    <img // eslint-disable-line @remotion/warn-native-media-tag -- onLoad releases the frame; <Img> hangs on some JPEGs
      src={resolveSrc(src)}
      alt=""
      style={style}
      onLoad={release}
      onError={release}
    />
  );
}

/** Fills a card edge-to-edge with an image, a video, or a gradient. */
function CardMedia({ src, t }: { src: string; t: KitTheme }) {
  const media: CSSProperties = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    objectFit: "cover",
  };
  const effective = src || placeholder(t);
  if (isGradient(effective)) {
    return <div style={{ ...media, background: effective }} />;
  }
  if (isVideo(effective)) {
    return (
      <OffthreadVideo
        showInTimeline={false}
        src={resolveSrc(effective)}
        muted
        style={media}
      />
    );
  }
  return <HeroImage src={effective} style={media} />;
}

/**
 * Cinematic product-launch hero — deterministic Remotion composition
 * (1280×720 @30fps). Two image cards, one continuous professionally-eased
 * motion, no bounce:
 *
 *   f0–40    the left image HOLDS full-screen, flat and clear
 *   f40      it recedes to its floating size and angles in about its inner edge
 *   f60      the right image slides in from the right; the two sit SYMMETRIC
 *            about the frame centre with an even, centred gap
 *   f100     both breathe with a barely-there float (never dead-static)
 *   f122     they fall off the lower edge together
 *   f126     the headline reveals and eases forward ("comes to front")
 *
 * Left/right/bottom edges dissolve into black. `image1`/`image2` + `heading`
 * are the props the video editor drives.
 */
function HeroLaunchScene({
  heading = "Launching today",
  image1 = staticFile("hero-launch/photo-4.jpg"),
  image2 = staticFile("hero-launch/photo-8.jpg"),
  theme,
  mode,
  fontFamily,
}: HeroLaunchProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode ?? "dark");
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;
  const s = height / 720;

  const cardW = 1000 * s;
  const cardH = 620 * s;
  const centerLeft = (width - cardW) / 2;
  const cardTop = 0.3 * height;
  // Symmetric about the centre → the gap sits exactly on the frame's midline.
  const restOffset = (cardW + GAP * s) / 2;
  const leftXFinal = -restOffset;
  const rightXFinal = restOffset;
  const rightXStart = 1.08 * width;
  const groupYFinal = 0.16 * height;

  // A clamped, eased 0→1 segment — the single motion primitive for the whole
  // scene. Easing lands cleanly on the target, so nothing ever "sticks".
  const seg = (start: number, dur: number, easing = OUT) =>
    interpolate(frame, [start, start + dur], [0, 1], {
      easing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  const recede = seg(40, 30); // full-screen → floating
  const angle = seg(46, 36); // flat → angled (rotateY only)
  const slideL = seg(46, 36); // centre → left rest
  const slideR = seg(60, 40); // offscreen right → right rest
  const drop = seg(122, 34, FALL); // settle → fall off bottom
  const title = seg(126, 40); // headline reveal + forward

  const leftScale = interpolate(recede, [0, 1], [1.5, 1]);
  const leftX = interpolate(slideL, [0, 1], [0, leftXFinal]);
  const leftDeg = interpolate(angle, [0, 1], [0, -TILT]);
  const leftOpacity = interpolate(frame, [2, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const rightX = interpolate(slideR, [0, 1], [rightXStart, rightXFinal]);
  const rightOpacity = interpolate(slideR, [0, 0.35], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Barely-there float once settled (fades out into the drop) so the held beat
  // reads as alive, not frozen — the classic "why does it feel stuck" fix.
  const floatEnv = seg(94, 22) * (1 - drop);
  const floatY = Math.sin(frame * 0.09) * 3.5 * s * floatEnv;
  const groupY = interpolate(drop, [0, 1], [0, groupYFinal]) + floatY;

  const titleY = interpolate(title, [0, 1], [40 * s, 0]);
  const titleScale = interpolate(title, [0, 1], [0.82, 1]);
  const titleBlur = interpolate(title, [0, 1], [10, 0]);

  const vignette = seg(50, 40, Easing.linear);

  const cardBox = (x: number, opacity: number): CSSProperties => ({
    position: "absolute",
    left: centerLeft,
    top: cardTop,
    width: cardW,
    height: cardH,
    opacity,
    transform: `translateX(${x}px)`,
  });

  // Opening zoom pivots on the centre; the tilt pivots on the inner edge.
  const zoom = (scale: number): CSSProperties => ({
    width: "100%",
    height: "100%",
    transform: `scale(${scale})`,
    transformOrigin: "center center",
  });
  const tilt = (deg: number, origin: string): CSSProperties => ({
    width: "100%",
    height: "100%",
    transform: `perspective(${PERSP * s}px) rotateY(${deg}deg)`,
    transformOrigin: origin,
  });
  const fade = (gradient: string): CSSProperties => ({
    position: "absolute",
    inset: 0,
    background: gradient,
  });

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: t.background, fontFamily: face }}
    >
      <AbsoluteFill
        showInTimeline={false}
        style={{ transform: `translateY(${groupY}px)` }}
      >
        {/* Each card is its own object to Remotion Studio (see `Item`). */}
        <Item index={0}>
          <div style={cardBox(leftX, leftOpacity)}>
            <div style={zoom(leftScale)}>
              {/* inner edge = right edge → pivot at 100% 50% */}
              <div style={tilt(leftDeg, "100% 50%")}>
                <ImageCard s={s} src={image1} t={t} />
              </div>
            </div>
          </div>
        </Item>
        <Item index={1}>
          <div style={cardBox(rightX, rightOpacity)}>
            {/* inner edge = left edge → pivot at 0% 50% */}
            <div style={tilt(TILT, "0% 50%")}>
              <ImageCard s={s} src={image2} t={t} />
            </div>
          </div>
        </Item>
      </AbsoluteFill>

      {/* Wide, clean edge dissolve — fades in after the full-screen opening. */}
      <AbsoluteFill
        showInTimeline={false}
        style={{ opacity: vignette, pointerEvents: "none" }}
      >
        <div
          style={fade(
            `linear-gradient(to left, ${t.background} 0%, transparent 30%)`,
          )}
        />
        <div
          style={fade(
            `linear-gradient(to right, ${t.background} 0%, transparent 22%)`,
          )}
        />
        <div
          style={fade(
            `linear-gradient(to top, ${t.background} 0%, transparent 30%)`,
          )}
        />
      </AbsoluteFill>

      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: 0.22 * height,
          padding: `0 ${40 * s}px`,
          textAlign: "center",
          color: t.foreground,
          fontWeight: 600,
          letterSpacing: "-0.02em",
          fontSize: 42 * s,
          opacity: title,
          filter: `blur(${titleBlur}px)`,
          transform: `translateY(${titleY}px) scale(${titleScale})`,
        }}
      >
        {heading}
      </div>
    </AbsoluteFill>
  );
}

/** A single card: one image (or video/gradient) filling it edge-to-edge. */
function ImageCard({ s, src, t }: { s: number; src: string; t: KitTheme }) {
  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        overflow: "hidden",
        borderRadius: 30 * s,
        background: mixOklch(t.background, t.card, 0.35),
        // Drop shadow + a subtle inset hairline ring so the edge reads on both
        // dark and bright media without dominating.
        boxShadow: `0 ${20 * s}px ${52 * s}px -${28 * s}px ${withAlpha(
          mixOklch(t.background, "#000", 0.75),
          0.9,
        )}, inset 0 0 0 1px ${withAlpha(t.foreground, 0.22)}`,
      }}
    >
      <CardMedia src={src} t={t} />
      {/* subtle depth: darken the lower edge + a hairline top sheen */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `linear-gradient(to top, ${withAlpha(
            mixOklch(t.background, "#000", 0.75),
            0.28,
          )} 0%, transparent 32%)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: 26 * s,
          right: 26 * s,
          top: 0,
          height: 1,
          background: `linear-gradient(90deg,transparent,${withAlpha(
            t.foreground,
            0.5,
          )},transparent)`,
        }}
      />
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one card at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function HeroLaunchPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}
type HeroLaunchCardValues = {
  readonly image?: string;
};

type HeroLaunchCardProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  HeroLaunchCardValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this card as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: HeroLaunchCardState) => void;
  };

/** What Studio is doing to one card right now, which the stage applies to its node. */
type HeroLaunchCardState = {
  values: HeroLaunchCardValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const HeroLaunchCardSchema = {
  ...Interactive.baseSchema,
  image: {
    type: "asset",
    assetType: "image",
    default: undefined,
    description: "Image",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One card: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the card is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const HeroLaunchCardInner = forwardRef<
  Element,
  HeroLaunchCardProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      image,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it, or when its parts move separately; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { image },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? HeroLaunchPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Card"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const HeroLaunchCard = Interactive.withSchema({
  Component: HeroLaunchCardInner,
  componentName: "<HeroLaunchCard>",
  schema: HeroLaunchCardSchema,
  supportsEffects: false,
});

type HeroLaunchStageProps = InteractiveBaseProps &
  ComponentProps<typeof HeroLaunchScene> & {
    readonly children?: ReactNode;
  };

/**
 * What a scene prop falls back to when Studio does not pass it, reset included.
 * The cards' own lists are here only for the scene's parameter defaults;
 * the stage always passes the ones its children build.
 */
const HeroLaunchDefaults = {
  image1: staticFile("hero-launch/photo-4.jpg"),
  image2: staticFile("hero-launch/photo-8.jpg"),
  heading: "Launching today",
  mode: "light",
  theme: { background: "transparent" },
} satisfies Partial<HeroLaunchStageProps>;

const HeroLaunchStageSchema = {
  ...Interactive.baseSchema,
  heading: {
    type: "text-content",
    default: "Launching today",
    description: "Headline",
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
} as const satisfies InteractivitySchema;

/** The scene's props, from its cards' values in order. */
const HeroLaunchFromItems = (o: readonly HeroLaunchCardValues[]) => ({
  image1: o[0]?.image || undefined,
  image2: o[1 % Math.max(o.length, 1)]?.image || undefined,
});

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function HeroLaunchFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

/** The host, told the frame inside the Element — the one its layers' timing is in. */
function HeroLaunchHosted({
  host,
  children,
}: {
  host: (frame: number) => ItemHost;
  children: ReactNode;
}) {
  return (
    <ItemHostProvider value={host(useCurrentFrame())}>
      {children}
    </ItemHostProvider>
  );
}

/**
 * The scene, with its cards as children. It reads their values to lay
 * the scene out, and hands each one back the node the scene draws it as.
 */
const HeroLaunchStageInner = forwardRef<
  HTMLDivElement,
  HeroLaunchStageProps & { readonly controls: SequenceControls | undefined }
>(
  (
    {
      controls,
      name,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      children,
      ...props
    },
    ref,
  ) => {
    const outlineRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
    // One empty box per card on the stage: the outline it falls back to,
    // which it moves over the part of itself that shows.
    const slots = useRef<{ current: HTMLDivElement | null }[]>([]);
    const slotFor = (i: number) => {
      slots.current[i] ??= { current: null };
      return slots.current[i];
    };
    // Every card the file lists, by position: each keeps its layer.
    const all = Children.toArray(children).filter(
      isValidElement,
    ) as ReactElement<HeroLaunchCardProps>[];
    const claims = useRef<{ current: Element | null }[]>([]);
    const claimFor = (j: number) => {
      claims.current[j] ??= { current: null };
      return claims.current[j];
    };
    const rest = { ...HeroLaunchDefaults, ...props };
    // What Studio is doing to each card that the file may not have yet.
    const [live, setLive] = useState<Record<number, HeroLaunchCardState>>({});
    const report = (j: number, state: HeroLaunchCardState) =>
      setLive((prev) =>
        JSON.stringify(prev[j]) === JSON.stringify(state)
          ? prev
          : { ...prev, [j]: state },
      );
    const merged = all.map((o, j) => {
      const st = live[j];
      return st
        ? {
            ...o.props,
            ...st.values,
            style: st.style,
            hidden: st.hidden,
            from: st.from,
            durationInFrames: st.durationInFrames,
          }
        : o.props;
    });
    // The ones the scene draws, in its order: the positions its `Item`s index.
    const kept = all.map((_, j) => j);
    const built = HeroLaunchFromItems(
      kept.map((j) => merged[j] as HeroLaunchCardValues),
    );
    const host =
      (frame: number): ItemHost =>
      (index, node) => {
        const j = kept[index];
        const m = j === undefined ? undefined : merged[j];
        if (j === undefined || !m) return node;
        // The layer's own visibility and timing, which its Sequence would apply
        // if it held the node.
        const start = m.from ?? 0;
        if (
          m.hidden ||
          frame < start ||
          frame >= start + (m.durationInFrames ?? Number.POSITIVE_INFINITY)
        )
          return null;
        const own = node as ReactElement<{
          ref?: Ref<Element>;
          style?: CSSProperties;
        }>;
        return cloneElement(own, {
          ref: claimFor(j),
          style: { ...own.props.style, ...m.style },
        });
      };
    // The scene measures its copy once, on mount, so a saved edit remounts it.
    // An edit still being typed does not: the scene would restart on every
    // keystroke. The layers are outside it and never remount with it.
    const key = JSON.stringify({
      ...rest,
      ...HeroLaunchFromItems(all.map((o) => o.props)),
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Product Hero"}
        controls={controls}
        outlineRef={outlineRef}
        width={1280}
        height={720}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
          }}
        >
          {/* First, so each box's ref is set before the objects that move it
              run their layout effects on a fresh mount. */}
          {all.map((_, j) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: one box per position
              key={j}
              ref={slotFor(j)}
              style={{
                position: "absolute",
                display: "none",
                pointerEvents: "none",
                opacity: 0,
              }}
            />
          ))}
          <HeroLaunchFade>
            <HeroLaunchHosted host={host}>
              <HeroLaunchScene key={key} {...rest} {...built} />
            </HeroLaunchHosted>
          </HeroLaunchFade>
          {/* The layers, after the scene: its nodes are attached by the time
              they measure them. */}
          {all.map((o, j) =>
            cloneElement(o, {
              // biome-ignore lint/suspicious/noArrayIndexKey: one layer per position
              key: j,
              claim: claimFor(j),
              slot: slotFor(j),
              report: (state: HeroLaunchCardState) => report(j, state),
            }),
          )}
        </div>
      </Sequence>
    );
  },
);

const HeroLaunchStage = Interactive.withSchema({
  Component: HeroLaunchStageInner,
  componentName: "<HeroLaunchStage>",
  schema: HeroLaunchStageSchema,
  supportsEffects: false,
});

